using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() now requires deterministic seed values.
        // DateTime.UtcNow is non-deterministic and will cause migrations to differ on every run.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfApp");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type" instead of
        // "Discriminator" by default for the discriminator property.
        // For existing documents that already store "Discriminator", you must explicitly
        // configure the old property name to avoid breaking existing data.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// --- Cosmos query service demonstrating sync-to-async migration ---
class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O with the Cosmos provider now throws
    // by default (InvalidOperationException). All queries must use async methods.
    public async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        // BEFORE (EF Core 8 - no longer works in 9):
        //   return db.Products.ToList();
        //
        // AFTER (EF Core 9 - must use async):
        return await db.Products.ToListAsync();
    }

    public async Task<Product?> FindProductAsync(CosmosDbContext db, string id)
    {
        // BEFORE: return db.Products.FirstOrDefault(p => p.Id == id);
        // AFTER:
        return await db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

