using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() can no longer be called within a
    // manual transaction. EF Core now manages its own transaction during migration.
    // Wrapping it in BeginTransaction() throws InvalidOperationException.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

